"""Asset builder worker: creates a real regression suite and health artifact."""

from __future__ import annotations

import argparse
import json
import os
import subprocess  # nosec B404 - bounded test execution with a fixed python path
import sys
from pathlib import Path
from typing import Any

from jarvis_foundry.orchestration.mission_context import MissionContext
from jarvis_foundry.orchestration.paths import sha256_file
from jarvis_foundry.orchestration.schemas import FileChange, TestRun, WorkerResult

TEST_TEMPLATE = '''\
"""R8 machinery regression suite for alpha_ledger (generated by asset worker)."""

from __future__ import annotations

from pathlib import Path

import pytest

from alpha_ledger.store import ConflictError, EventStore, IntegrityError


def _store(tmp_path: Path) -> EventStore:
    return EventStore(tmp_path / "events.jsonl")


def test_empty_store_verifies(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.verify()
    assert store.event_count() == 0


def test_append_returns_increasing_sequences(tmp_path: Path) -> None:
    store = _store(tmp_path)
    first = store.append({"kind": "a", "value": 1}, idempotency_key="k1")
    second = store.append({"kind": "b", "value": 2}, idempotency_key="k2")
    assert second == first + 1


def test_append_is_idempotent_by_key(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.append({"kind": "a"}, idempotency_key="same")
    count = store.event_count()
    store.append({"kind": "a"}, idempotency_key="same")
    assert store.event_count() == count


def test_conflicting_key_raises(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.append({"kind": "a"}, idempotency_key="same")
    with pytest.raises(ConflictError):
        store.append({"kind": "b"}, idempotency_key="same")


def test_tampered_payload_raises(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.append({"kind": "a", "value": "original"}, idempotency_key="k1")
    raw_path = tmp_path / "events.jsonl"
    lines = raw_path.read_text(encoding="utf-8").splitlines()
    tampered = lines[0].replace("original", "TAMPERED")
    raw_path.write_text(tampered + "\\n", encoding="utf-8")
    with pytest.raises(IntegrityError):
        store.verify()


def test_malformed_line_raises(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.append({"kind": "a"}, idempotency_key="k1")
    raw_path = tmp_path / "events.jsonl"
    raw_path.write_text(raw_path.read_text(encoding="utf-8") + "not-json\\n", encoding="utf-8")
    with pytest.raises(IntegrityError):
        store.verify()


def test_state_hash_changes_on_append(tmp_path: Path) -> None:
    store = _store(tmp_path)
    before = store.state_hash()
    store.append({"kind": "a"}, idempotency_key="k1")
    assert store.state_hash() != before


def test_read_returns_payloads_in_order(tmp_path: Path) -> None:
    store = _store(tmp_path)
    store.append({"kind": "a"}, idempotency_key="k1")
    store.append({"kind": "b"}, idempotency_key="k2")
    assert [record["kind"] for record in store.read()] == ["a", "b"]
'''

HEALTH_TEMPLATE = """\
# Alpha Ledger Health Artifact

Generated by the R8 asset builder worker inside an isolated clone and verified
independently by the R8 machinery before acceptance.

## What is verified

- Append-only JSONL event store with per-line payload hashes.
- Idempotent appends by idempotency key.
- Tamper detection and malformed line rejection.
- Deterministic state hash and ordered reads.

## Commands

```text
python -m pytest tests -q
```

## Current status

PASS at acceptance time. This artifact is regenerated on each mission; it is not
authority for any later state.
"""


def _write_asset_files(clone: Path) -> list[Path]:
    test_path = clone / "tests" / "test_regression_edges.py"
    test_path.parent.mkdir(parents=True, exist_ok=True)
    test_path.write_text(TEST_TEMPLATE, encoding="utf-8")
    health_path = clone / "docs" / "health.md"
    health_path.parent.mkdir(parents=True, exist_ok=True)
    health_path.write_text(HEALTH_TEMPLATE, encoding="utf-8")
    return [test_path, health_path]


def _run_suite(clone: Path, python: Path) -> dict[str, Any]:
    env = dict(os.environ)
    env["PYTHONPATH"] = str(clone / "src")
    completed = subprocess.run(  # nosec B603 B607 - no shell, fixed python path
        [str(python), "-m", "pytest", "tests", "-q", "--junitxml=test-results.xml"],
        cwd=str(clone),
        capture_output=True,
        text=True,
        timeout=1200,
        env=env,
        check=False,
    )
    return {
        "exit_code": completed.returncode,
        "output": completed.stdout + completed.stderr,
    }


def _build_result(
    clone: Path, files: list[Path], suite: dict[str, Any], python: Path
) -> WorkerResult:
    changes = tuple(
        FileChange(
            path=path.relative_to(clone).as_posix(),
            action="added",
            sha256=sha256_file(path),
            size=path.stat().st_size,
        )
        for path in files
    )
    passed = suite["exit_code"] == 0
    tests = (
        TestRun(
            name="pytest tests -q",
            passed=passed,
            exit_code=suite["exit_code"],
            summary=suite["output"].strip().splitlines()[-1] if suite["output"].strip() else "",
            evidence_path="test-results.xml",
        ),
    )
    return WorkerResult(
        status="PASS" if passed else "FAIL",
        claims={"asset_type": "regression_suite", "files_created": len(changes)},
        files_changed=changes,
        commands_run=(f"{python} -m pytest tests -q --junitxml=test-results.xml",),
        tests=tests,
        evidence=("test-results.xml",),
        artifacts=("docs/health.md",),
        external_effects={"protected_repos": 0, "owner_projects": 0, "live_state": 0},
        blockers=() if passed else ("worker suite failed",),
        uncertainty="low",
        recommended_next_action="machinery verification and acceptance",
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mission", required=True, type=Path)
    parser.add_argument("--clone", required=True, type=Path)
    parser.add_argument("--result", required=True, type=Path)
    args = parser.parse_args(argv)
    mission = MissionContext.from_dict(json.loads(args.mission.read_text(encoding="utf-8")))
    spec = dict(mission.worker_spec)
    if spec.get("asset_type") != "regression_suite":
        raise RuntimeError("asset worker received unsupported worker spec")
    clone = args.clone.resolve()
    files = _write_asset_files(clone)
    suite = _run_suite(clone, Path(sys.executable))
    result = _build_result(clone, files, suite, Path(sys.executable))
    args.result.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(json.dumps(result.to_dict(), sort_keys=True))
    return 0 if result.status == "PASS" else 1


if __name__ == "__main__":
    sys.exit(main())
